+    async fn ensure_piece(kit: &Arc<crate::kit::Kit>, design_id: &Id, piece_id: &Id) -> Result<Arc<crate::kit::design::piece::Piece>, ComposeError> {
+        let design = kit.design_by_external_id(design_id).await.ok_or_else(|| ComposeError::not_found("Design", design_id.as_str()))?;
