+    fn validate_attribute_ids(expected: usize, actual: &[Id]) -> Result<(), ComposeError> {
+        if expected != actual.len() {
+            return Err(ComposeError::invalid(format!("attribute id count mismatch: expected {}, got {}", expected, actual.len())));
+        }
+        Ok(())
+    }
